    "note": "△PAB の底辺を AB に固定すると、面積は高さ（P と直線 AB の距離）に比例する。だから面積が最大になるのは、P が直線 AB から一番遠くなるときである。直線 AB と平行な直線 y＝x＋k を考え、k を小さくしていくと、この直線は放物線に1点だけで接する位置に来る。その接点が一番遠い点 P になる。「1点で接する」は、連立した2次方程式が重解（解が1つ）になる、と言いかえられる。",
