    "note": "行動の手がかりを集める。①ほかの道具は布にくるまれているのに、この時計だけは革のバンドが柔らかく光っている（毎日磨かれている）。②直らないと分かっていて毎日巻く。③巻き終えて満足そうにうなずく。",
